    "commentaries": [
      {
        "author": "Rashi (1040–1105)",
        "text": "Despre <span class=\"heb-inline\">הַתַּנִּינִם הַגְּדֹלִים</span> („monștrii marini cei mari”), Rashi notează, urmând o tradiție midrașică, că e vorba despre Leviatan și perechea sa — dar Dumnezeu a ucis femela (sau a castrat perechea) și a sărat-o pentru masa celor drepți în Lumea Viitoare, ca vietățile astea uriașe să nu se înmulțească necontrolat și să distrugă lumea."
      },
      {
        "author": "Context cultural-istoric (Orientul Apropiat Antic)",
        "text": "Mitul mesopotamian al lui Labbu vorbește despre un șarpe de mare uriaș, de zeci de leghe lungime, pe care zeii trebuie să-l vâneze și să-l învingă printr-un efort dramatic. În Geneza, monștrii marini nu sunt rivali ai lui Dumnezeu, ci pur și simplu creaturile Lui, create la fel ca toate celelalte, printr-un simplu cuvânt — fără nicio luptă, fără nicio amenințare la adresa ordinii cosmice. E un mod indirect, dar limpede, de a spune că nici cele mai înfricoșătoare ființe din mitologiile vecine nu sunt zei sau puteri cosmice rivale, ci simple animale, supuse aceluiași Creator ca toate celelalte."
      },
      {
        "author": "Ibn Ezra (1089–1167)",
        "text": "Discută verbul „se târăște” aplicat aici vietăților acvatice — o observație lingvistică despre felul mișcării, nu doar despre locul unde trăiesc aceste creaturi."
      },
      {
        "author": "Sforno (cca. 1475–1550)",
        "text": "Explică „monștrii marini” prin puterea generativă limitată a apei, care singură n-ar fi fost suficientă pentru a produce aceste creaturi fără sămânță — Dumnezeu a trebuit să creeze o putere specială, suplimentară, pentru acest act."
      }
    ],
    "textCompare": [
      {
        "source": "Textul Masoretic (ebraică)",
        "original": "וַיִּבְרָא אֱלֹהִים אֶת־הַתַּנִּינִם הַגְּדֹלִים וְאֵת כָּל־נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵהֶם וְאֵת כָּל־עוֹף כָּנָף לְמִינֵהוּ וַיַּרְא אֱלֹהִים כִּי־טוֹב",
        "translation": "„Și Dumnezeu a creat monștrii marini cei mari, și toate vietățile de care mișună apele, după soiurile lor; și orice zburătoare înaripată după soiul ei. Și Dumnezeu a văzut că este bine.” — traducerea rabinului Rosen.",
        "note": ""
      },
      {
        "source": "Septuaginta (greacă)",
        "original": "καὶ ἐποίησεν ὁ Θεὸς τὰ κήτη τὰ μεγάλα καὶ πᾶσαν ψυχὴν ζῴων ἑρπετῶν, ἃ ἐξήγαγεν τὰ ὕδατα κατὰ γένη αὐτῶν, καὶ πᾶν πετεινὸν πτερωτὸν κατὰ γένος· καὶ εἶδεν ὁ Θεὸς ὅτι καλά.",
        "greek": true,
        "translation": "„Și a făcut Dumnezeu chiturile cele mari și tot sufletul vietăților târâtoare, pe care le-au scos apele, după felurile lor, și orice pasăre înaripată după fel; și a văzut Dumnezeu că sunt bune.”",
        "note": "κῆτος (ketos, „chit, monstru marin”) — cuvântul din spatele „balenei” lui Iona în traducerile grecești ale acelei cărți — traduce תַּנִּינִם, confirmând citirea „monștri marini uriași”, nu pur și simplu „pești mari”."
      },
      {
        "source": "Pentateuhul Samaritean",
        "original": "(scris cu alfabetul samaritean)",
        "translation": "Diferență reală, confirmată: ויברא אלהים את התנינים הגדלים ואת כל נפש החיה הרמשת אשר שרצו המים למיניהם ואת כל עוף כנף למינהו וירא אלהים כי טוב — „Și a creat Dumnezeu chiții cei mari și toate vietățile care se mișcă și de care mișună apele, după soiul lor, și toate păsările înaripate după soiul lor. Și a văzut Dumnezeu că este bine.”",
        "note": "(Sursă: Schorch, ed., The Samaritan Pentateuch: A Critical editio maior (2018), ms. Chester Beatty 751.)"
      }
    ],
    "fidela": "Şi Dumnezeu a creat balene mari şi fiecare vieţuitoare care se mişcă, pe care apele le-au dat abundent, după felul lor, şi fiecare pasăre înaripată, după felul ei; şi Dumnezeu a văzut că lucrul acesta era bun."
