    "commentaries": [
      {
        "author": "Rashi (1040–1105)",
        "text": "Notează ordinea enumerării — dobitoace, târâtoare, sălbăticiuni — și o compară cu ordinea de la v. 25, unde apare inversată (sălbăticiuni, apoi dobitoace, apoi târâtoare). Pentru Rashi, ordinea din porunca lui Dumnezeu (v. 24) nu trebuie să coincidă neapărat cu ordinea împlinirii (v. 25) — un tipar pe care îl vede și la vegetație (v. 11-12)."
      },
      {
        "author": "Ibn Ezra (1089–1167)",
        "text": "Distinge patru categorii: „suflet viu” ca termen general pentru orice ființă generată din foc, apă și pământ (inclusiv omul), „dobitoace” — cele aflate lângă om, pentru călărit și hrană —, „târâtoare” — vietăți mici de pe pământ —, și „fiarele pământului” — cele din sălbăticie, neîmblânzite."
      }
    ],
    "textCompare": [
      {
        "source": "Textul Masoretic (ebraică)",
        "original": "וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ־אֶרֶץ לְמִינָהּ וַיְהִי־כֵן",
        "translation": "„Și Dumnezeu a spus: «Pământul să scoată la iveală vietăți, [fiecare] după soiul său: dobitoc, târâtoare și sălbăticiune a pământului, după soiul său!» Și a fost așa.” — traducerea rabinului Rosen.",
        "note": ""
      },
      {
        "source": "Septuaginta (greacă)",
        "original": "καὶ εἶπεν ὁ Θεός Ἐξαγαγέτω ἡ γῆ ψυχὴν ζῶσαν κατὰ γένος, τετράποδα καὶ ἑρπετὰ καὶ θηρία τῆς γῆς κατὰ γένος· καὶ ἐγένετο οὕτως.",
        "greek": true,
        "translation": "„Și a zis Dumnezeu: «Să scoată pământul suflet viu după fel, patrupede și târâtoare și fiare ale pământului după fel!» Și a fost așa.”",
        "note": "LXX „τετράποδα” („patrupede”) e o alegere mai descriptivă decât ebraicul „behemah” (dobitoc/animal domestic), care nu specifică numărul de picioare."
      },
      {
        "source": "Pentateuhul Samaritean",
        "original": "(scris cu alfabetul samaritean)",
        "translation": "Diferență reală, confirmată: ויאמר אלהים תוצא הארץ נפש חיה למינה בהמה ורמש וחית הארץ למינה ויהי כן — „Și a zis Dumnezeu: «Să dea pământul vietăți după soiul lor: vite, târâtoare și fiare ale pământului, după soiul lor!»” Și așa a fost.",
        "note": "(Sursă: Schorch, ed., The Samaritan Pentateuch: A Critical editio maior (2018), ms. Chester Beatty 751.)"
      }
    ],
    "fidela": "Şi Dumnezeu a spus: Să dea pământul fiinţa vie după felul ei, vite şi târâtoare şi fiare ale pământului, după felul lor. Şi aşa a fost."
